 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != background]
    # Every diagonal pair of equal-colored marks identifies a ray. Extend
    # the pair's diagonal line in both directions, stopping at other marks.
    lines = set()
    for r, c, color in seeds:
        for dr, dc in ((1, 1), (1, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                lines.add((r, c, dr, dc, color))
    for r, c, dr, dc, color in lines:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] != background and grid[rr][cc] != color:
                    break
                out[rr][cc] = color
                rr += sign * dr
                cc += sign * dc
    return out
